mapper.select:
SELECT GROUP_ID, OWNER_ID, TITLE, AMOUNT, MONTHS, STATUS
FROM GYE_GROUP
WHERE GROUP_ID = #{groupId}

SELECT COUNT(*)
FROM GYE_MEMBER
WHERE GROUP_ID  = #{groupId}
AND MEMBER_ID = #{memberId}
AND STATUS    = 'ACTIVE'

SELECT COUNT(*)
FROM PAYMENT_PROOF
WHERE GROUP_ID  = #{groupId}
AND MEMBER_ID = #{memberId}
AND PAY_MONTH = #{payMonth}
AND ROUND_NO  = #{roundNo}

SELECT COUNT(*)
FROM PAYMENT_PROOF_FILE
WHERE FILE_HASH = #{fileHash}

    AND PAYMENT_PROOF_ID != #{excludeProofId}

mapper.insert:

    SELECT SEQ_PAYMENT_PROOF_FILE.NEXTVAL FROM DUAL

INSERT INTO PAYMENT_PROOF_FILE (
FILE_ID, PAYMENT_PROOF_ID, SORT_NO, FILE_PATH, ORIGIN_NAME,
MIME_TYPE, FILE_SIZE, FILE_HASH, ENCRYPTED_YN, KEY_VER
) VALUES (
#{fileId}, #{paymentProofId}, #{sortNo}, #{filePath}, #{originName},
#{mimeType}, #{fileSize}, #{fileHash}, #{encryptedYn}, #{keyVer}
)

mapper.select:
SELECT p.PAYMENT_PROOF_ID AS paymentProofId, p.GROUP_ID AS groupId, g.TITLE AS groupTitle, p.MEMBER_ID AS memberId, m.NAME AS memberName, p.PAY_MONTH AS payMonth, p.ROUND_NO AS roundNo, p.AMOUNT AS amount, p.PAY_DATE AS payDate, p.STATUS AS status, p.REF_NO AS refNo, p.REVIEW_MEMO AS reviewMemo, p.RESUBMIT_COUNT AS resubmitCount, p.CREATED_AT AS createdAt, (SELECT COUNT(*) FROM PAYMENT_PROOF_FILE f WHERE f.PAYMENT_PROOF_ID = p.PAYMENT_PROOF_ID) AS fileCount FROM PAYMENT_PROOF p JOIN GYE_GROUP g ON g.GROUP_ID = p.GROUP_ID JOIN MEMBER m ON m.MEMBER_ID = p.MEMBER_ID WHERE p.GROUP_ID = #{groupId}
AND p.MEMBER_ID = #{memberId}
ORDER BY p.PAY_MONTH DESC, p.ROUND_NO DESC, p.PAYMENT_PROOF_ID DESC

SELECT FILE_PATH
FROM PAYMENT_PROOF_FILE
WHERE PAYMENT_PROOF_ID = #{proofId}

mapper.update:
UPDATE OVERDUE_CASE
SET STATUS      = 'RESOLVED',
RESOLVED_AT = SYSDATE
WHERE GROUP_ID  = #{groupId}
AND MEMBER_ID = #{memberId}
AND PAY_MONTH = #{payMonth}
AND STATUS   != 'RESOLVED'
